    <div class="container">
        <div class="main-content" id="main-content">
            <header>
                <h1> Tiffy AI</h1>
                <p class="subtitle">Prémium AI képgenerálás</p>
                <button class="beta-btn" onclick="openBetaMenu()"> BETA FUNKCIÓK</button>
            </header>

            <div class="generator-section">
                <h2 class="section-title">Tiffy AI</h2>
                <form id="tiffy-form">
                    <div class="form-group">
                        <label for="tiffy-prompt">Szöveg prompt:</label>
                        <textarea id="tiffy-prompt" placeholder="Írja le, milyen képet szeretne generálni..." required></textarea>
                    </div>

                    <div class="form-group">
                        <label for="tiffy-aspect-ratio">Képarány:</label>
                        <select id="tiffy-aspect-ratio">
                            <option value="1:1">1:1 (Négyzet)</option>
                            <option value="9:16">9:16 (Portré)</option>
                            <option value="16:9">16:9 (Tájkép)</option>
                            <option value="4:3">4:3 (Klasszikus)</option>
                            <option value="3:4">3:4 (Portré klasszikus)</option>
                        </select>
                    </div>

                    <button type="submit" class="btn"Képek generálása</button>
                </form>
            </div>

            <div class="loading" id="loading">
                <div class="spinner"></div>
                <p id="loading-text">Képek generálása folyamatban...</p>
            </div>

            <div class="result-section" id="result-section">
                <div class="result-grid" id="result-grid"></div>
            </div>
        </div>

        <div class="beta-overlay" id="beta-overlay">
            <div class="beta-menu">
                <button class="close-beta" onclick="closeBetaMenu()">&times;</button>
                <h2> BETA Funkciók</h2>
                <div class="beta-option" onclick="closeBetaMenu();">
                     Tiffy AI
                </div>
            </div>
        </div>
    </div>

    <script>
        function openBetaMenu() {
            document.getElementById('beta-overlay').classList.add('active');
            document.getElementById('main-content').classList.add('blurred');
        }

        function closeBetaMenu() {
            document.getElementById('beta-overlay').classList.remove('active');
            document.getElementById('main-content').classList.remove('blurred');
        }

        function showLoading(text) {
            document.getElementById('loading-text').textContent = text;
            document.getElementById('loading').classList.add('active');
        }

        function hideLoading() {
            document.getElementById('loading').classList.remove('active');
        }

        function displayResult(data) {
            const resultGrid = document.getElementById('result-grid');
            resultGrid.innerHTML = '';

            data.results.forEach(result => {
                const resultItem = document.createElement('div');
                resultItem.className = 'result-item';

                if (result.success) {
                    resultItem.innerHTML = `
                        <h3>🎨 Generált kép</h3>
                        <img src="${result.image_url}" alt="Generált kép">
                        <br>
                        💾 Letöltés
                    `;
                } else {
                    resultItem.innerHTML = `
                        <h3>❌ Hiba történt</h3>
                        <div class="error">Hiba: ${result.error}</div>
                    `;
                }

                resultGrid.appendChild(resultItem);
            });
        }

        function displayError(message) {
            const resultGrid = document.getElementById('result-grid');
            resultGrid.innerHTML = `<div class="error">${message}</div>`;
        }

        // Form event listener
        document.getElementById('tiffy-form').addEventListener('submit', async (e) => {
            e.preventDefault();

            const formData = {
                prompt: document.getElementById('tiffy-prompt').value,
                aspect_ratio: document.getElementById('tiffy-aspect-ratio').value
            };

            showLoading('Képek generálása folyamatban...');

            try {
                const response = await fetch('/generate_combined', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                    body: JSON.stringify(formData)
                });

                const data = await response.json();

                if (data.success) {
                    displayResult(data);
                } else {
                    displayError(data.error || 'Ismeretlen hiba történt');
                }
            } catch (error) {
                displayError(`Hálózati hiba: ${error.message}`);
            } finally {
                hideLoading();
            }
        });

        // Close beta menu when clicking outside
        document.getElementById('beta-overlay').addEventListener('click', (e) => {
            if (e.target === document.getElementById('beta-overlay')) {
                closeBetaMenu();
            }
        });
    </script>
