    <script>
        function openBetaMenu() {
            document.getElementById('beta-overlay').classList.add('active');
            document.getElementById('main-content').classList.add('blurred');
        }

        function closeBetaMenu() {
            document.getElementById('beta-overlay').classList.remove('active');
            document.getElementById('main-content').classList.remove('blurred');
        }

        function showLoading(text) {
            document.getElementById('loading-text').textContent = text;
            document.getElementById('loading').classList.add('active');
        }

        function hideLoading() {
            document.getElementById('loading').classList.remove('active');
        }

        function displayResult(data) {
            const resultGrid = document.getElementById('result-grid');
            resultGrid.innerHTML = '';

            data.results.forEach(result => {
                const resultItem = document.createElement('div');
                resultItem.className = 'result-item';

                if (result.success) {
                    resultItem.innerHTML = `
                        <h3>🎨 Generált kép</h3>
                        <img src="${result.image_url}" alt="Generált kép">
                        <br>
                        💾 Letöltés
                    `;
                } else {
                    resultItem.innerHTML = `
                        <h3>❌ Hiba történt</h3>
                        <div class="error">Hiba: ${result.error}</div>
                    `;
                }

                resultGrid.appendChild(resultItem);
            });
        }

        function displayError(message) {
            const resultGrid = document.getElementById('result-grid');
            resultGrid.innerHTML = `<div class="error">${message}</div>`;
        }

        // Form event listener
        document.getElementById('tiffy-form').addEventListener('submit', async (e) => {
            e.preventDefault();

            const formData = {
                prompt: document.getElementById('tiffy-prompt').value,
                aspect_ratio: document.getElementById('tiffy-aspect-ratio').value
            };

            showLoading('Képek generálása folyamatban...');

            try {
                const response = await fetch('/generate_combined', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                    body: JSON.stringify(formData)
                });

                const data = await response.json();

                if (data.success) {
                    displayResult(data);
                } else {
                    displayError(data.error || 'Ismeretlen hiba történt');
                }
            } catch (error) {
                displayError(`Hálózati hiba: ${error.message}`);
            } finally {
                hideLoading();
            }
        });

        // Close beta menu when clicking outside
        document.getElementById('beta-overlay').addEventListener('click', (e) => {
            if (e.target === document.getElementById('beta-overlay')) {
                closeBetaMenu();
            }
        });
    </script>
