## **main.py**

```python
from flask import Flask, render_template, request, jsonify, send_file
import replicate, os, requests
from io import BytesIO
import uuid

app = Flask(__name__)

api_token = os.environ.get('REPLICATE_API_TOKEN')
replicate_client = replicate.Client(api_token=api_token)

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/generate_combined', methods=['POST'])
def generate_combined():
    d = request.get_json()
    p = d.get('prompt', '')
    ar = d.get('aspect_ratio', '1:1')
    if not p:
        return jsonify({'error': 'A szöveg prompt szükséges'}), 400
    r = []
    try:
        o = replicate_client.run("google/imagen-4-ultra", input={"prompt": p, "aspect_ratio": ar, "safety_filter_level": "block_medium_and_above", "output_format": "png"})
        u = str(o[0]) if isinstance(o, list) and o else str(o)
        r.append({'model': 'Google Imagen 4 Ultra', 'image_url': u, 'success': True})
    except Exception as e:
        r.append({'model': 'Google Imagen 4 Ultra', 'error': str(e), 'success': False})
    try:
        o = replicate_client.run("black-forest-labs/flux-1.1-pro-ultra", input={"prompt": p, "aspect_ratio": ar, "safety_tolerance": 3})
        u = str(o[0]) if isinstance(o, list) and o else str(o)
        r.append({'model': 'Flux 1.1 Pro Ultra', 'image_url': u, 'success': True})
    except Exception as e:
        r.append({'model': 'Flux 1.1 Pro Ultra', 'error': str(e), 'success': False})
    return jsonify({'success': True, 'prompt': p, 'results': r})

@app.route('/download')
def download_image():
    u = request.args.get('url')
    if not u:
        return "Nincs kép URL megadva", 400
    try:
        resp = requests.get(u)
        resp.raise_for_status()
        img = BytesIO(resp.content)
        img.seek(0)
        fn = f"generated_image_{uuid.uuid4().hex[:8]}.png"
        return send_file(img, mimetype='image/png', as_attachment=True, download_name=fn)
    except Exception as e:
        return f"Hiba a kép letöltésekor: {str(e)}", 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, debug=os.environ.get('FLASK_DEBUG','False').lower()=='true')
